import os, base64
R = "LockCOC" if os.path.isdir("LockCOC") else "."
def P(p): return os.path.join(R, p)
def rd(p): return open(P(p), encoding="utf-8").read()
def w(p, s): open(P(p), "w", encoding="utf-8").write(s)
def sub(s, old, new, what):
    if old not in s: raise SystemExit("[loi] khong thay doan can sua: " + what)
    return s.replace(old, new, 1)
d = P("static/downloads")
if not os.path.isdir(d): raise SystemExit("[loi] khong thay thu muc static/downloads")
if os.path.exists(P("static/js/tour.js")): raise SystemExit("[loi] da ap dung patch34 roi")
open(os.path.join(d, "tour.mp4"), "wb").write(base64.b64decode(""))
open(os.path.join(d, "tour-poster.jpg"), "wb").write(base64.b64decode(""))
w("static/js/tour.js", '''"use strict";
/* tour.js - video giao diện app: tự phát khi cuộn tới, có nút tạm dừng */
(function () {
  var v = document.getElementById("tour-vid"), b = document.getElementById("tour-btn");
  if (!v || !b) return;
  var paused = false, still = window.matchMedia && matchMedia("(prefers-reduced-motion: reduce)").matches;
  function label() { b.textContent = v.paused ? "Phát" : "Tạm dừng"; }
  b.addEventListener("click", function () { if (v.paused) { paused = false; v.play().catch(function () {}); } else { paused = true; v.pause(); } label(); });
  if ("IntersectionObserver" in window) {
    new IntersectionObserver(function (es) {
      es.forEach(function (e) { if (e.isIntersecting && !paused && !still) v.play().catch(function () {}); else v.pause(); label(); });
    }, { threshold: 0.45 }).observe(v);
  }
  label();
})();
''')
w("static/landing.css", rd("static/landing.css") + """
.tour { text-align: center; }
.tour-col { display: grid; justify-items: center; gap: 14px; margin-top: 18px; position: relative; }
.tour-col::before { content: ""; position: absolute; inset: 6% -10% 10%; z-index: -1; border-radius: 50%; background: radial-gradient(closest-side, rgba(226,176,74,.3), rgba(226,176,74,0) 72%); filter: blur(26px); }
.tour-in { width: min(84vw, 330px); aspect-ratio: 828 / 1900; border-radius: 28px; overflow: hidden; background: #0b0906; box-shadow: 0 30px 60px rgba(0,0,0,.5), 0 0 0 1px rgba(226,176,74,.25); }
.tour-in video { width: 100%; height: 100%; display: block; object-fit: cover; }
.tour-btn { padding: 6px 14px; border-radius: 999px; background: rgba(14,12,8,.7); color: #fff; font: inherit; font-size: 13px; border: 1px solid rgba(255,255,255,.2); cursor: pointer; }
""")
L = rd("templates/landing.html")
sec = '''    <section id="giao-dien" class="block tour">
      <h2>Xem giao diện app</h2>
      <p class="sub">Một vòng nhanh: camera, đăng bài, bảng tin, chat, thống kê và thư viện.</p>
      <div class="tour-col">
        <div class="tour-in"><video id="tour-vid" muted loop playsinline preload="metadata" poster="/static/downloads/tour-poster.jpg" aria-label="Video giao diện LockCOC: camera, đăng bài, bảng tin, chat, thống kê, thư viện"><source src="/static/downloads/tour.mp4" type="video/mp4"></video></div>
        <button class="tour-btn" id="tour-btn" type="button">Tạm dừng</button>
        <p class="cap-note">Ảnh và dữ liệu trong video là mẫu.</p>
      </div>
    </section>

'''
L = sub(L, '    <section id="tinh-nang" class="block">', sec + '    <section id="tinh-nang" class="block">', "section")
L = sub(L, '  <script src="/static/js/landing.js"></script>', '  <script src="/static/js/landing.js"></script>\n  <script src="/static/js/tour.js"></script>', "script")
w("templates/landing.html", L)
print("[ok] patch34 xong: da them video giao dien")
